<?php
require 'config.php'; require 'auth.php'; requireLogin(); $id=(int)($_GET['id']??0); $tx=read_data('transactions'); $idx=find_index($tx,$id); if($idx===null){$_SESSION['flash']=['type'=>'error','message'=>'Riwayat transaksi tidak ditemukan.'];redirect('stock_history.php');} $row=$tx[$idx]; $items=read_data('items'); $itemIdx=find_index($items,$row['item_id']); if($itemIdx!==null){ if($row['type']==='IN'&&$items[$itemIdx]['stock']<$row['quantity']){$_SESSION['flash']=['type'=>'error','message'=>'Riwayat masuk tidak bisa dihapus karena stok sudah digunakan.'];redirect('stock_history.php');} $items[$itemIdx]['stock'] += $row['type']==='IN' ? -$row['quantity'] : $row['quantity']; write_data('items',$items);} array_splice($tx,$idx,1); write_data('transactions',$tx); $_SESSION['flash']=['type'=>'success','message'=>'Riwayat dihapus dan stok disesuaikan.']; redirect('stock_history.php');